let failedCount = 0;

testCases.forEach((tc) => {
  console.log(`[${tc.id}] ${tc.name}`);
  console.log(`Input snippet: "${tc.text.slice(0, 80)}${tc.text.length > 80 ? '...' : ''}"`);
  
  // 1. Light Check (Hard Rules)
  const light = sw.lightcheck(tc.text);
  
  // 2. Full Check (Current Present-Only ML)
  const result = sw.spamcheck(tc.text);
  
  // 3. Manual Bernoulli Math (using _baseScore and _featureWeight)
  const presentFeatures = sw._transform(tc.text);
  const nClasses = sw._classes.length;
  
  // Present-only scores (current implementation) for comparison
  const scores = new Float64Array(nClasses);
  for (let c = 0; c < nClasses; c++) {
    let s = sw._classLogPrior[c];
    for (let k = 0; k < presentFeatures.length; k++) {
      s += sw._featureLogProb[c][presentFeatures[k]];
    }
    scores[c] = s;
  }
  const offsetSpamScore = scores[1] - 8.0;
  
  const bernoulliScores = new Float64Array(nClasses);
  for (let c = 0; c < nClasses; c++) {
    let s = sw._baseScore[c];
    for (let k = 0; k < presentFeatures.length; k++) {
      s += sw._featureWeight[c][presentFeatures[k]];
    }
    bernoulliScores[c] = s;
  }
  
  // Apply the same calibration offset to Spam (c=1)
  const rawBernoulliSpam = bernoulliScores[1];
  const offsetBernoulliSpam = bernoulliScores[1] - 8.0;
  const rawBernoulliSafe = bernoulliScores[0];
  const bernoulliIsSpam = offsetBernoulliSpam > rawBernoulliSafe;
  
  // Calculate Bernoulli probability
  const maxB = Math.max(rawBernoulliSafe, offsetBernoulliSpam);
  const expB0 = Math.exp(rawBernoulliSafe - maxB);
  const expB1 = Math.exp(offsetBernoulliSpam - maxB);
  const sumB = expB0 + expB1;
  const bernoulliProb = sumB > 0 ? expB1 / sumB : 0.5;

  const currentPass = result.isSpam === tc.expectedSpam;
  const bernoulliPass = bernoulliIsSpam === tc.expectedSpam;
  
  if (!bernoulliPass) {
    failedCount++;
  }
  
  console.log(`  - Lightcheck:       ${light.isSpam ? '🔴 TRIGGERED (' + light.reason + ')' : '🟢 Safe'}`);
  console.log(`  - Present-Only ML:  ${result.isSpam ? '🔴 SPAM' : '🟢 SAFE'} -> ${currentPass ? '✅ PASS' : '❌ FAIL'} (Prob: ${(result.prob * 100).toFixed(4)}%)`);
  console.log(`  - Bernoulli ML:     ${bernoulliIsSpam ? '🔴 SPAM' : '🟢 SAFE'} -> ${bernoulliPass ? '✅ PASS' : '❌ FAIL'} (Prob: ${(bernoulliProb * 100).toFixed(4)}%)`);
  console.log(`  - Present-Only:     Safe = ${scores[0].toFixed(2)} | Spam (offset) = ${offsetSpamScore.toFixed(2)}`);
  console.log(`  - Bernoulli:        Safe = ${rawBernoulliSafe.toFixed(2)} | Spam (offset) = ${offsetBernoulliSpam.toFixed(2)}`);
  
  if (bernoulliIsSpam || tc.id === "TC-09-CASINO" || tc.id === "TC-10-PDPA") {
    const featuresWithWeights = presentFeatures.map(index => {
      const word = invVocab[index] || `[index:${index}]`;
      const lp0 = sw._featureLogProb[0][index];
      const lp1 = sw._featureLogProb[1][index];
      const w0 = sw._featureWeight[0][index];
      const w1 = sw._featureWeight[1][index];
      const diff = w1 - w0;
      const lpDiff = lp1 - lp0;
      return { word, index, lp0, lp1, w0, w1, diff, lpDiff };
    });
    featuresWithWeights.sort((a, b) => b.diff - a.diff);
    console.log(`  - Feature Weights (Bernoulli weight diff vs raw logProb diff):`);
    featuresWithWeights.slice(0, 10).forEach((f, idx) => {
      console.log(`      ${idx + 1}. "${f.word}" -> Bernoulli Diff: ${f.diff.toFixed(2)} (Raw Diff: ${f.lpDiff.toFixed(2)}) | w0: ${f.w0.toFixed(2)}, w1: ${f.w1.toFixed(2)} | lp0: ${f.lp0.toFixed(2)}, lp1: ${f.lp1.toFixed(2)}`);
    });
  }
  console.log('----------------------------------------------------------------\n');
});

